49	export type HostingResult = { ok?: boolean; error?: string; accountId?: string };
50	
51	// The active-ish states that reserve a domain / occupy a node slot.
52	const LIVE_STATES = ["PENDING", "PROVISIONING", "ACTIVE", "SUSPENDED"] as const;
53	
54	/** Least-loaded enabled+online node with account headroom. */
55	async function scheduleHostingNode(): Promise<{ id: string } | null> {
56	  const nodes = await db.hostingNode.findMany({ where: { enabled: true, status: "ONLINE" } });
57	  if (!nodes.length) return null;
58	  const loads = await Promise.all(
59	    nodes.map(async (n) => ({
60	      node: n,
61	      used: await db.hostingAccount.count({ where: { hostingNodeId: n.id, status: { in: [...LIVE_STATES] } } }),
62	    })),
63	  );
64	  const withRoom = loads.filter((l) => l.used < l.node.maxAccounts).sort((a, b) => a.used - b.used);
65	  return withRoom.length ? { id: withRoom[0].node.id } : null;
66	}
67	
68	/** A free jailed username on the node, derived from the email + random salt. */
69	async function pickUsername(nodeId: string, emailSeed: string): Promise<string> {
70	  for (let i = 0; i < 8; i++) {
71	    const name = deriveUsername(emailSeed, randomBytes(4).toString("hex"));
72	    if (!isValidUnixUsername(name)) continue;
73	    const taken = await db.hostingAccount.findUnique({ where: { hostingNodeId_username: { hostingNodeId: nodeId, username: name } } });
74	    if (!taken) return name;
75	  }
76	  throw new Error("Could not allocate a username — try again.");
77	}
