79	/**
80	 * Order a shared-hosting account for a domain on a plan. Same purchase discipline
81	 * as every other paid path: no spending while impersonating, verified email,
82	 * wallet charge in the same tx that creates the record. The account starts
83	 * PENDING; the worker provisioner brings it up (inert until shared hosting is
84	 * enabled — see worker/hosting.ts).
85	 */
86	export async function orderHostingAccount(
87	  planId: string,
88	  domain: string,
89	  termMonthsRaw?: number,
90	): Promise<HostingResult> {
91	  const user = await requireUser();
92	  await assertNotImpersonating();
93	  const unverified = await emailVerificationError(user);
94	  if (unverified) return { error: unverified };
95	
96	  // OPTIONAL domain. An empty domain means "start me on a free temporary
97	  // `<username>.nxeon.cloud` subdomain, I'll connect a real domain later" — the
98	  // customer is never forced to own a domain to sign up. A REAL domain keeps every
99	  // cross-tenant guard it always had; the temp subdomain is derived from the
100	  // account's own per-node-unique username (below) so it can't collide with
101	  // anything a customer typed, and its uniqueness is still enforced by the SAME
102	  // atomic UNIQUE(hostname) claim inside the charge tx.
103	  const wantTemp = !String(domain ?? "").trim();
104	  let name = "";
105	  if (!wantTemp) {
106	    name = normalizeHostingDomain(domain);
107	    if (!name) return { error: "Enter a domain." };
108	    if (!isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
109	  }
110	
111	  const plan = await db.hostingPlan.findUnique({ where: { id: planId } });
112	  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
113	
114	  if (!wantTemp) {
115	    // One account per domain across ALL customers — same cross-tenant guard as
116	    // email subscriptions (a shared vhost keys on server_name).
117	    const dupe = await db.hostingAccount.findFirst({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } });
118	    if (dupe) {
119	      return {
120	        error:
121	          dupe.userId === user.id
122	            ? "You already have a hosting account for this domain."
123	            : "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across.",
124	      };
125	    }
126	    // Also reject if this hostname is already someone's subdomain or addon domain
127	    // (audit HIGH-2: the primary-order guard used to ignore those two tables).
128	    if (await isHostnameClaimed(name)) {
129	      return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
130	    }
131	  }
132	
133	  const node = await scheduleHostingNode();
134	  if (!node) return { error: "No shared-hosting capacity is available right now — please try again shortly." };
135	
136	  // Managed first-month-free. `promoCharge` is $0 (a single-month hosting term is
137	  // free); `fullCharge` is the plan price. The credit is granted ONLY if the atomic
138	  // claim inside the charge tx succeeds — otherwise (already redeemed by this
139	  // account/IP, or the promo is off) the account is created at FULL price. We
140	  // pre-check eligibility only to pick the balance gate: a first-time customer with
141	  // a $0 balance can still sign up free, a repeat one is gated against full price.
142	  // First-month-free is scoped to Shared Web Hosting (this flow) — the one
143	  // product the promo applies to. See firstMonthFreeAppliesTo.
144	  const promoEnabled = firstMonthFreeAppliesTo("HOSTING") && (await firstMonthFreeEnabled());
145	  const campaign = promoCampaignFromCookie(await cookies());
146	  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
147	  // Billing term (Monthly / Annual). The annual rate is the admin setting, resolved
148	  // ONCE here, frozen onto the account, charged up front and read back at renewal —
149	  // so displayed === charged === renewed. A malformed term falls back to monthly.
150	  const term = normalizeProductTerm(termMonthsRaw);
151	  const annualPct = await annualDiscountPct();
152	  const fullCharge = termPriceCents(plan.priceCents, term, annualPct);
153	  // First-month-free must credit EXACTLY ONE MONTH — never zero a whole annual term.
154	  // `firstMonthCreditCents(fullCharge, term)` returns the full charge for a 1-month
155	  // term (genuinely free first month, $0) and one month's share for the annual term,
156	  // so annual + promo = "one month credited, the other 11 months charged".
157	  const promoCharge = Math.max(0, fullCharge - firstMonthCreditCents(fullCharge, term));
158	  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
159	  const anticipated = eligible ? promoCharge : fullCharge;
160	  if (user.balanceCents < anticipated) return { error: "Insufficient balance. Top up your wallet first." };
161	
162	  const limits = planLimits(plan);
163	  const username = await pickUsername(node.id, user.email.split("@")[0] ?? "acct");
164	  // Free temporary subdomain: derived from the just-allocated (per-node-unique)
165	  // username, validated the same way a real domain is and de-duplicated by the same
166	  // atomic hostname claim inside the tx. The advisory pre-check here is friendly UX
167	  // only — a collision across nodes is caught authoritatively by UNIQUE(hostname).
168	  if (wantTemp) {
169	    name = tempSubdomainFor(username);
170	    if (!isValidHostingDomain(name)) return { error: "Couldn’t allocate a temporary subdomain — please try again." };
171	    if (await isHostnameClaimed(name)) return { error: "Couldn’t allocate a temporary subdomain — please try again." };
172	  }
173	
174	  let accountId = "";
175	  try {
176	    await db.$transaction(async (tx) => {
177	      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
178	      let debitCents = fullCharge;
179	      let promoClaimId: string | null = null;
180	      // MONEY BUG FIX (2026-08-12): gate the claim on `eligible`, NOT `promoEnabled`.
181	      // claimFirstMonthFree INSERTs a redemption row and catches the P2002 unique
182	      // violation ("already redeemed") to return {claimed:false}. But Postgres POISONS
183	      // the whole transaction the instant any statement fails — a caught error does
184	      // NOT un-abort it — so the very next statement (debitWallet's updateMany) then
185	      // dies with 25P02 ("current transaction is aborted"). Result: EVERY repeat
186	      // customer who already used the free month could no longer place a hosting order
187	      // (the order failed, wallet never charged). `eligible` is the same authoritative
188	      // per-user/per-IP precheck (firstMonthFreeEligible) resolved above, so an
189	      // ineligible/repeat customer now skips the doomed INSERT entirely and is charged
190	      // full price cleanly. The atomic anti-double-grant guarantee is preserved: two
191	      // concurrent ELIGIBLE orders still both run the claim, one wins, the loser's tx
192	      // poisons on P2002 and fails safe (no charge, no second free month) — retry pays
193	      // full. So exactly one free month is ever granted.
194	      if (eligible) {
195	        const claim = await claimFirstMonthFree(tx, {
196	          userId: user.id,
197	          ipHash,
198	          serviceType: "HOSTING",
199	          campaign,
200	          chargedCents: promoCharge,
201	        });
202	        if (claim.claimed) {
203	          debitCents = promoCharge;
204	          promoClaimId = claim.id;
205	        }
206	      }
207	      const note = debitCents < fullCharge ? " — First month free" : "";
208	      // Term shown on the ledger line: an annual account reads "Annual ($X.XX/mo)"
209	      // so the customer sees the yearly commitment AND its real per-month rate.
210	      const effMonthly = term > 1 ? Math.round(fullCharge / term) : 0;
211	      const termLabel = term > 1 ? `${vpsTerm(term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(term).label;
212	      await debitWallet(tx, user.id, debitCents);
213	      await tx.walletTransaction.create({
214	        data: { userId: user.id, amountCents: -debitCents, description: `Web Hosting: ${plan.name} for ${name} — ${termLabel}${note}` },
215	      });
216	      const acct = await tx.hostingAccount.create({
217	        // Cast: the symlinked prod Prisma client's types predate `termMonths` /
218	        // `annualDiscountPct` on HostingAccount until it is regenerated at deploy
219	        // (identical at runtime then — see lib/order.ts's Server create).
220	        data: {
221	          userId: user.id,
222	          hostingNodeId: node.id,
223	          planId: plan.id,
224	          username,
225	          primaryDomain: name,
226	          status: "PENDING",
227	          diskQuotaMB: limits.diskGB * 1024,
228	          maxSites: limits.maxSites,
229	          maxDatabases: limits.maxDatabases,
230	          // The term this account was SOLD on, and the annual rate frozen at sale, so
231	          // the renewal sweep bills the SAME price it was ordered at (worker/product-renewals.ts).
232	          termMonths: term,
233	          annualDiscountPct: annualPct,
234	          expiresAt: addMonths(new Date(), term),
235	        } as Prisma.HostingAccountUncheckedCreateInput,
236	      });
237	      accountId = acct.id;
238	      // Atomic hostname claim in the SAME tx as the account row. A colliding
239	      // primaryDomain (another order, or someone's subdomain/addon of the same
240	      // name racing us past the advisory isHostnameClaimed check) fails here on
241	      // UNIQUE(hostname) → the whole tx (incl. the wallet debit) rolls back.
242	      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(name), accountId: acct.id, kind: "PRIMARY" } });
243	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, acct.id, debitCents);
244	    });
245	  } catch (e) {
246	    if (isUniqueViolation(e)) {
247	      return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
248	    }
249	    // The generic message below is intentionally opaque to the customer, but the
250	    // REAL error must be diagnosable server-side (e.g. prod schema drift: a
251	    // HostingAccount.termMonths/annualDiscountPct column or the HostingHostnameClaim
252	    // table missing because a `prisma db push` didn't apply → the INSERT throws
253	    // here). Log it before swallowing. No money-logic change — the tx already rolled
254	    // back, so the wallet was NOT charged.
255	    console.error("[hosting.order] failed", {
256	      userId: user.id,
257	      planId,
258	      domain: name,
259	      code: (e as { code?: string })?.code,
260	      err: e instanceof Error ? e.message : e,
261	    });
262	    return { error: "Couldn’t place the order. Your wallet was not charged — try again." };
263	  }
264	
265	  await db.auditLog.create({ data: { userId: user.id, action: "hosting.order", detail: `${plan.name} · ${name}` } }).catch(() => {});
266	  revalidatePath("/dashboard/hosting");
267	  return { ok: true, accountId };
268	}
269	
270	// ---------- Checkout wizard (payment-method-captured order) ------------------
271	//
272	// THE MONEY FIX. `orderHostingAccount` above debits the WALLET only. First-month-
273	// free (hosting-only) makes a monthly plan $0 for month 1, so the wallet path used
274	// to provision with NOTHING on file — and month-2's renewal had nothing to charge.
275	// `placeHostingOrder` is the wizard's single entry point and closes that gap: it
276	// REFUSES to provision unless the account has a way to bill the renewal (a saved
277	// card OR a wallet balance that already covers one renewal), it is idempotent
278	// against double-submit, and it then delegates the ACTUAL charge to the audited
279	// `orderHostingAccount` above — one debit path, never a second one.
280	//
281	// displayed === charged === renewed: this action computes NO price of its own for
282	// the debit. The wallet debit + the first-month-free reserve→confirm→release
283	// atomicity all live inside `orderHostingAccount`; `renewalCents` here is only the
284	// gate threshold and is the SAME `termPriceCents(plan.priceCents, term, annualPct)`
285	// the renewal sweep charges (worker/product-renewals.ts hostingRenewalPrice).
286	
287	export type HostingOrderInput = {
288	  planId: string;
289	  /** Empty/omitted => free temporary `<username>.nxeon.cloud` subdomain. */
290	  domain?: string;
291	  termMonths?: number;
292	  /** Optional catalog app to auto-install after the account provisions. */
293	  appSlug?: string;
294	  /** Client-generated token that makes a resubmit a no-op (double-submit guard). */
295	  idempotencyKey: string;
296	};
297	
298	export type HostingOrderResult =
299	  | { ok: true; accountId: string }
300	  | { error: string }
301	  /** No renewal-capable payment method yet — the wizard must capture a card first. */
302	  | { needCard: true; renewalCents: number };
303	
304	/**
305	 * The full-price single renewal of a plan/term — the gate threshold, identical to
306	 * what the renewal sweep bills so "wallet covers a renewal" means exactly that.
307	 */
308	async function hostingRenewalCents(plan: { priceCents: number }, term: number): Promise<number> {
309	  const annualPct = await annualDiscountPct();
310	  return termPriceCents(plan.priceCents, term, annualPct);
311	}
312	
313	/** Place a hosting order from the checkout wizard. See the block comment above. */
314	export async function placeHostingOrder(input: HostingOrderInput): Promise<HostingOrderResult> {
315	  const user = await requireUser();
316	  await assertNotImpersonating();
317	  const unverified = await emailVerificationError(user);
318	  if (unverified) return { error: unverified };
319	
320	  const key = String(input.idempotencyKey ?? "").trim();
321	  if (!/^[A-Za-z0-9_-]{8,64}$/.test(key)) return { error: "Couldn’t place the order — please reload and try again." };
322	
323	  const term = normalizeProductTerm(input.termMonths);
324	  const plan = await db.hostingPlan.findUnique({ where: { id: input.planId } });
325	  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
326	
327	  // RENEWAL-METHOD GATE — the core fix. Never provision a paid product with no way
328	  // to bill the renewal. A saved card (charged off-session by the renewal sweep) OR
329	  // a wallet already holding one renewal's worth qualifies; otherwise the wizard
330	  // sends the customer to Stripe to capture a card (which also handles the $0-today
331	  // case, where no card would otherwise be collected).
332	  const renewalCents = await hostingRenewalCents(plan, term);
333	  if (!hasChargeableCard(user) && user.balanceCents < renewalCents) {
334	    return { needCard: true, renewalCents };
335	  }
336	
337	  // IDEMPOTENCY — reuse the audited FulfilledSession one-winner primitive (its
338	  // UNIQUE(stripeSessionId) is what the card path leans on) rather than inventing a
339	  // token table. A rapid resubmit or a network retry with the same key can't create
340	  // a second account or take a second debit.
341	  const sessionKey = `hostorder:${key}`;
342	  try {
343	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
344	  } catch (e) {
345	    if (isUniqueViolation(e)) {
346	      const prior = await db.fulfilledSession.findUnique({ where: { stripeSessionId: sessionKey } });
347	      // A completed prior attempt: replay its result (no second charge).
348	      if (prior?.status === "DONE" && prior.detail) return { ok: true, accountId: prior.detail };
349	      // A failed prior attempt: clear it so an explicit retry can proceed.
350	      if (prior?.status === "FAILED") {
351	        await db.fulfilledSession.delete({ where: { stripeSessionId: sessionKey } }).catch(() => {});
352	      } else {
353	        // Still in flight (CLAIMED): a concurrent submit is placing it right now.
354	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
355	      }
356	      // Retry after clearing a FAILED marker: re-claim, or bail if we lost the race.
357	      try {
358	        await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
359	      } catch {
360	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
361	      }
362	    } else {
363	      throw e;
364	    }
365	  }
366	
367	  // Delegate the ACTUAL charge to the audited wallet path. An empty domain routes to
368	  // the free temporary subdomain. All money movement, the first-month-free atomic
369	  // claim and the hostname claim happen inside orderHostingAccount's transaction.
370	  const res = await orderHostingAccount(input.planId, input.domain ?? "", term);
371	  if (res.error || !res.accountId) {
372	    await db.fulfilledSession
373	      .update({ where: { stripeSessionId: sessionKey }, data: { status: "FAILED", detail: (res.error ?? "order failed").slice(0, 500) } })
374	      .catch(() => {});
375	    return { error: res.error ?? "Couldn’t place the order. Your wallet was not charged — try again." };
376	  }
377	  await db.fulfilledSession
378	    .update({ where: { stripeSessionId: sessionKey }, data: { status: "DONE", detail: res.accountId } })
379	    .catch(() => {});
380	
381	  // Optional one-click app install: queue it now so the worker installs it the
382	  // moment the account finishes provisioning. Best-effort — a bad slug never voids
383	  // the (already-charged) order; the customer can install from the panel later.
384	  const slug = String(input.appSlug ?? "").trim();
385	  if (slug) {
386	    try {
387	      await queueHostingAppInstall(res.accountId, slug, plan.maxDatabases, user.email);
388	    } catch {
389	      /* non-fatal: the account is created and charged; the app can be installed later */
390	    }
391	  }
392	
393	  revalidatePath("/dashboard/hosting");
394	  return { ok: true, accountId: res.accountId };
395	}
396	
397	/**
398	 * Queue an APP_INSTALL for a freshly-ordered (PENDING) account. Mirrors installApp
399	 * but without the ACTIVE gate — the task waits in the queue and the worker runs it
400	 * after provisioning. Generates DB credentials up front for apps that need one.
401	 */
402	async function queueHostingAppInstall(accountId: string, slug: string, maxDatabases: number, email: string): Promise<void> {
403	  const app = hostingAppCatalog().find((x) => x.slug === slug);
404	  if (!app) return;
405	  let payload: Record<string, unknown> = { slug };
406	  if (app.needsDb) {
407	    if (maxDatabases < 1) return; // the plan has no DB budget — skip rather than fail
408	    const acct = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { username: true } });
409	    if (!acct) return;
410	    const dbName = `${acct.username}_${slug}`.slice(0, 64);
411	    const dbUser = dbName.slice(0, 32);
412	    const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
413	    payload = { slug, dbName, dbUser, dbPassEnc: encryptSecret(dbPass) };
414	  }
415	  void email;
416	  await db.hostingTask.create({ data: { accountId, kind: "APP_INSTALL", payload: JSON.stringify(payload) } });
417	}
418	
419	/**
420	 * Begin capturing a renewal payment method for the hosting wizard. A Stripe hosted
421	 * Checkout in `mode: "setup"` records a card + off-session mandate WITHOUT charging
422	 * anything — the answer to "a $0 first month must still capture a card for renewal".
423	 * Returns to the hosting page; the wizard finalises via finalizeCardSetup (shared).
424	 */
425	export async function startHostingCardSetup(): Promise<{ url?: string; error?: string }> {
426	  await assertNotImpersonating();
427	  const user = await requireUser();
428	  if (!stripeConfigured()) return { error: "Card payments aren’t configured on this installation yet." };
429	  try {
430	    const url = await createCardSetupSession(user, "/dashboard/hosting");
431	    if (!url) return { error: "Stripe didn’t return a setup link. Please try again." };
432	    await db.auditLog.create({ data: { userId: user.id, action: CARD_SETUP_STARTED } });
433	    return { url };
434	  } catch (e) {
435	    console.error("[hosting] card setup session failed", e);
436	    return { error: "We couldn’t start card setup just now. Please try again in a moment." };
437	  }
438	}
