440	export type HostingAccountView = {
441	  id: string;
442	  primaryDomain: string;
443	  planName: string;
444	  status: string;
445	  username: string;
446	  pointToA: string;
447	  pointToCname: string | null;
448	  diskQuotaMB: number;
449	  diskUsedMB: number | null;
450	  inodesUsed: number | null;
451	  usageAt: string | null;
452	  maxSites: number;
453	  maxDatabases: number;
454	  sslActive: boolean;
455	  // Serve-verification health (from hostingHealthSweep). null until first checked.
456	  // serveHttpOk/serveHttpsOk = whether nginx actually answers on 80/443 for this
457	  // domain; healthNote drives the DNS→HTTPS stepper; healthCheckedAt timestamps it.
458	  serveHttpOk: boolean | null;
459	  serveHttpsOk: boolean | null;
460	  healthNote: string | null;
461	  healthCheckedAt: string | null;
462	  phpVersion: string;
463	  phpVersions: string[];
464	  // The installed Adminer DB-manager URL path (/nxtools-<token>/adminer.php), or
465	  // null until the customer installs it from the Databases tab.
466	  dbToolPath: string | null;
467	  error: string | null;
468	  expiresAt: string | null;
