564	/** Create a scoped database for an account (within the plan's maxDatabases). */
565	export async function createHostingDatabase(accountId: string, label: string): Promise<{ error?: string; ok?: boolean; password?: string }> {
566	  const user = await requireUser();
567	  await assertNotImpersonating();
568	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, username: true, maxDatabases: true } });
569	  if (!a) return { error: "Account not found." };
570	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
571	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
572	  // A short, safe suffix keyed off the account username: <user>_<slug>.
573	  const slug = String(label ?? "").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db";
574	  const name = `${a.username}_${slug}`.slice(0, 64);
575	  const dbUser = name.slice(0, 32);
576	  if (!/^[a-z0-9_]{1,64}$/.test(name)) return { error: "Invalid database name." };
577	  const password = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
578	  // Count + create in ONE serializable transaction, so concurrent creates can't
579	  // both read a stale count and blow past the plan cap (audit 2026-08-01 TOCTOU).
580	  try {
581	    await db.$transaction(async (tx) => {
582	      const n = await tx.hostingDatabase.count({ where: { accountId: a.id, status: { in: ["PENDING", "ACTIVE"] } } });
583	      if (n >= a.maxDatabases) throw new Error("CAP");
584	      await tx.hostingDatabase.create({ data: { accountId: a.id, name, dbUser, passwordEnc: encryptSecret(password), status: "PENDING" } });
585	    }, { isolationLevel: "Serializable" });
586	  } catch (e) {
587	    if (e instanceof Error && e.message === "CAP") return { error: `Your plan allows ${a.maxDatabases} database${a.maxDatabases === 1 ? "" : "s"}.` };
588	    // Serialization conflict (P2034) or the unique(accountId,name) collision.
589	    return { error: "A database with that name already exists, or the request raced — try again." };
590	  }
591	  revalidatePath("/dashboard/hosting");
592	  // Shown ONCE — the encrypted copy is cleared by the provisioner after it applies it.
593	  return { ok: true, password };
594	}
