605	/**
606	 * Install the per-account Adminer database manager (or return the existing one).
607	 * Owner-or-admin + not-impersonating (same discipline as every resource-creating
608	 * action). Queues an INSTALL_DBTOOL task that drops Adminer into THIS account's
609	 * webroot at a randomized path served by the account's own FPM socket. The
610	 * customer logs in with their own SCOPED DB user, so a leaked path grants no
611	 * cross-tenant access (see the worker handler's SECURITY note). Idempotent: if the
612	 * tool is already installed, returns its path without re-queuing.
613	 */
614	export async function installDbTool(accountId: string): Promise<{ ok?: boolean; error?: string; url?: string }> {
615	  const user = await requireUser();
616	  await assertNotImpersonating();
