618	  if (!a) return { error: "Account not found." };
619	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
620	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
621	  if (a.dbToolPath) return { ok: true, url: a.dbToolPath };
622	  // Don't queue a second install while one is already in flight.
