626	  if (!isValidDbToolToken(token)) return { error: "Couldn’t start the install — try again." };
627	  const path = `/nxtools-${token}/adminer.php`;
628	  await db.hostingTask.create({ data: { accountId, kind: "INSTALL_DBTOOL", payload: JSON.stringify({ token, path }) } });
629	  revalidatePath(`/dashboard/hosting/${accountId}`);
630	  return { ok: true };
