735	/** The higher plans an account may move UP to (never a downgrade): active plans
736	 *  priced at-or-above and disk at-or-above the current plan, and strictly larger
737	 *  in at least one, excluding the current plan. Owner or admin. */
738	export async function listHostingUpgradePlans(accountId: string): Promise<{ currentPlanName?: string; plans?: UpgradePlanView[]; error?: string }> {
739	  const user = await requireUser();
740	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { plan: true } });
741	  if (!a) return { error: "Account not found." };
