743	  const cur = a.plan;
744	  const all = await db.hostingPlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });
745	  const plans = all
746	    .filter((p) => p.id !== cur.id && p.priceCents >= cur.priceCents && p.diskGB >= cur.diskGB && (p.priceCents > cur.priceCents || p.diskGB > cur.diskGB))
747	    .map((p) => ({
748	      id: p.id, name: p.name, priceCents: p.priceCents, diskGB: p.diskGB, maxSites: p.maxSites,
749	      maxDatabases: p.maxDatabases, bandwidthTB: p.bandwidthTB, tagline: p.tagline,
