755	/**
756	 * Move a hosting account UP to a larger plan. Same purchase discipline as
757	 * orderHostingAccount: no spending while impersonating, wallet charge in the same
758	 * tx that mutates the account.
759	 *
760	 * Billing choice (kept simple + honest): we charge the FULL per-term price
761	 * DIFFERENCE (new − current) now, and leave the renewal date unchanged; future
762	 * terms bill at the new plan price. No mid-term proration or refunds — that keeps
763	 * the flow one debit and never owes the customer money back. The customer sees the
764	 * exact delta before confirming. Only UP is allowed (a downgrade would need a
765	 * refund path we don't have).
766	 */
767	export async function upgradeHostingPlan(accountId: string, newPlanId: string): Promise<HostingResult> {
768	  const user = await requireUser();
769	  await assertNotImpersonating();
770	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { plan: true } });
771	  if (!a) return { error: "Account not found." };
772	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
773	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
774	  const newPlan = await db.hostingPlan.findUnique({ where: { id: newPlanId } });
775	  if (!newPlan || !newPlan.active) return { error: "That plan isn’t available." };
776	  if (newPlan.id === a.planId) return { error: "You’re already on this plan." };
777	  const cur = a.plan;
778	  // Up-only guard (re-checked server-side; never trust the client's picker).
779	  if (newPlan.priceCents < cur.priceCents || newPlan.diskGB < cur.diskGB) {
780	    return { error: "You can only move to a larger plan." };
781	  }
782	  const limits = planLimits(newPlan);
783	  const chargeCents = Math.max(0, newPlan.priceCents - cur.priceCents);
784	  if (user.balanceCents < chargeCents) return { error: "Insufficient balance. Top up your wallet first." };
785	
786	  try {
787	    await db.$transaction(async (tx) => {
788	      if (chargeCents > 0) {
789	        await debitWallet(tx, user.id, chargeCents);
790	        await tx.walletTransaction.create({
791	          data: { userId: user.id, amountCents: -chargeCents, description: `Web Hosting upgrade: ${cur.name} → ${newPlan.name} for ${a.primaryDomain}` },
792	        });
793	      }
794	      // Snapshot the new plan's limits onto the account (same as orderHostingAccount
795	      // does at creation), so a later plan edit can't silently re-quota this account.
796	      // phpVersion is left as-is: an upgrade only widens the allowed set.
797	      await tx.hostingAccount.update({
798	        where: { id: a.id },
799	        data: { planId: newPlan.id, diskQuotaMB: limits.diskGB * 1024, maxSites: limits.maxSites, maxDatabases: limits.maxDatabases },
800	      });
801	      // Enact the node-level change (raise disk quota + rewrite FPM pool).
802	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "APPLY_PLAN_LIMITS" } });
803	    });
804	  } catch (e) {
805	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance. Top up your wallet first." };
806	    return { error: "Couldn’t upgrade the plan. Your wallet was not charged — try again." };
807	  }
808	
809	  await db.auditLog.create({ data: { userId: user.id, action: "hosting.upgrade", detail: `${cur.name} → ${newPlan.name} · ${a.primaryDomain}` } }).catch(() => {});
810	  revalidatePath(`/dashboard/hosting/${accountId}`);
811	  return { ok: true };
812	}
