921	/**
922	 * Is this hostname already claimed ANYWHERE? A shared node routes purely by nginx
923	 * `server_name`, and a hostname can live in THREE places — a primary domain, a
924	 * subdomain, or an addon domain. Before this, each creator only checked its own
925	 * table, so an addon could shadow a victim's subdomain (or vice-versa) on a
926	 * co-located node = cross-tenant vhost takeover (security audit HIGH-1/HIGH-2).
927	 *
928	 * This is now a FAST, FRIENDLY PRE-CHECK only — good UX (an early, clear error)
929	 * but NOT trusted alone: a non-atomic read can't stop two concurrent requests
930	 * from both passing it and both committing the same server_name (the co-tenant
931	 * vhost-shadowing TOCTOU). The authoritative guard is the atomic UNIQUE(hostname)
932	 * insert into HostingHostnameClaim done INSIDE each creator's transaction — a
933	 * colliding claim fails there (P2002) and rolls the whole tx back.
934	 */
935	async function isHostnameClaimed(name: string): Promise<boolean> {
936	  // The authoritative registry (single UNIQUE(hostname) spanning all three kinds)
937	  // is the fast, definitive pre-check now. We also still scan the three resource
938	  // tables so any legacy row created before the claims table existed is honoured.
939	  const host = normalizeClaimHostname(name);
940	  const [claim, prim, sub, addon] = await Promise.all([
941	    db.hostingHostnameClaim.count({ where: { hostname: host } }),
942	    db.hostingAccount.count({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } }),
943	    db.hostingSubdomain.count({ where: { fqdn: name, status: { in: [...SITE_STATES] } } }),
944	    db.hostingAddonDomain.count({ where: { domain: name, status: { in: [...SITE_STATES] } } }),
945	  ]);
946	  return claim + prim + sub + addon > 0;
947	}
