348	/** Create ONE scoped MySQL/MariaDB user+db on the account's node. */
349	async function provisionHostingDatabase(dbId: string): Promise<void> {
350	  const rec = await db.hostingDatabase.findUnique({ where: { id: dbId }, include: { account: { include: { node: true } } } });
351	  if (!rec || rec.status !== "PENDING") return;
352	  if (SANDBOX || !ENABLED) {
353	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: SANDBOX ? "ACTIVE" : "PENDING", passwordEnc: null, error: SANDBOX ? null : "Shared hosting not enabled." } });
354	    return;
355	  }
356	  const name = rec.name;
357	  const user = rec.dbUser;
358	  const pass = rec.passwordEnc ? decryptSecret(rec.passwordEnc) : "";
359	  // DB name + user were built from the validated username; re-assert shape.
360	  if (!/^[a-z0-9_]{1,64}$/.test(name) || !/^[a-z0-9_]{1,32}$/.test(user) || !pass) {
361	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "FAILED", error: "invalid db identifiers" } });
362	    return;
363	  }
364	  try {
365	    const conn = await connectNode(rec.account.node);
366	    try {
367	      // Grants scoped to THIS database only — the data-isolation boundary.
368	      // buildScopedGrantSql escapes _/% so the GRANT can't bleed onto a peer's db.
369	      const sql = sqlForMysqlExec(buildScopedGrantSql(name, user, pass));
370	      await run(conn, "create database", `mysql -e "${sql}"`);
371	    } finally {
372	      try { conn.end(); } catch { /* */ }
373	    }
374	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "ACTIVE", passwordEnc: null, error: null } });
375	  } catch (e) {
376	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "FAILED", error: (e instanceof Error ? e.message : String(e)).slice(0, 300) } });
377	  }
378	}
