/**
 * Reveal a hosting database's stored password (owner or admin, never while
 * impersonating — same discipline as revealHostingSftpPassword, audit LOW-1). The
 * password is kept encrypted on the row now (the provisioner no longer wipes it),
 * so a customer can look it up any time. If it was never stored (a legacy row, or a
 * WordPress/app DB from before this shipped), they can Reset to set a fresh one.
 */
export async function revealHostingDbPassword(dbId: string): Promise<{ password?: string; error?: string }> {
  const user = await requireUser();
  await assertNotImpersonating();
  const d = await db.hostingDatabase.findUnique({
    where: { id: dbId },
    select: { passwordEnc: true, account: { select: { userId: true } } },
  });
  if (!d) return { error: "Not found." };
  if (d.account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (!d.passwordEnc) return { error: "No stored password — reset it to set a new one." };
  return { password: decryptSecret(d.passwordEnc) };
}

/**
 * Reset a hosting database's password (owner or admin, never while impersonating).
 * Generates a new alphanumeric password, queues a RESET_DB_PASSWORD task that runs
 * `ALTER USER … IDENTIFIED BY …` on the node, and stores the new (encrypted) value
 * so it can be viewed later. Returned ONCE to the caller for display. No money logic.
 */
export async function resetHostingDbPassword(dbId: string): Promise<{ password?: string; error?: string }> {
  const user = await requireUser();
  await assertNotImpersonating();
  const d = await db.hostingDatabase.findUnique({
    where: { id: dbId },
    select: { id: true, dbUser: true, accountId: true, account: { select: { userId: true } } },
  });
  if (!d) return { error: "Not found." };
  if (d.account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  const newPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
  await db.hostingTask.create({
    data: {
      accountId: d.accountId,
      // New enum value applied by `prisma db push` at promote (additive/safe; the
      // symlinked prod Prisma client's types predate it until regenerated — cast,
      // identical at runtime, same pattern as HostingAccount.termMonths above).
      kind: "RESET_DB_PASSWORD" as Prisma.HostingTaskUncheckedCreateInput["kind"],
      payload: JSON.stringify({ dbUser: d.dbUser, passEnc: encryptSecret(newPass) }),
    },
  });
  await db.hostingDatabase.update({ where: { id: d.id }, data: { passwordEnc: encryptSecret(newPass) } });
  revalidatePath("/dashboard/hosting");
  return { password: newPass };
}

