// The one-click installer menu shown in the hosting deploy wizard. It is the
// enriched superset of the raw app catalog: WordPress FIRST (it installs via its
// own fully-automated WORDPRESS_INSTALL task, so it is NOT in hostingAppCatalog()),
// then every APP_RECIPES download the worker actually supports — so the wizard can
// never offer an app the worker can't install. Each item carries a short blurb and,
// where available, a Simple Icons brand glyph for a real logo.
//
// Server-only: `simple-icons` is a build dependency resolved at install time, and
// the icon lookup never reaches the client.

// Namespace import (never named) — a computed key lookup can't produce a build-time
// "export not found", so an unknown/removed brand simply resolves to `undefined` at
// runtime and falls through to the initial-tile fallback. EXACTLY as
// components/marketing/CompetitorLogo.tsx resolves its marks.
import * as simpleIcons from "simple-icons";
import { hostingAppCatalog } from "../worker/hosting";

export type HostingAppMenuItem = {
  slug: string;
  name: string;
  needsDb: boolean;
  blurb: string;
  /** Simple Icons SVG path (24×24 viewBox), or undefined for a fallback initial tile. */
  logoPath?: string;
  /** The brand's official hex, if the wizard ever wants to tint on hover. */
  logoHex?: string;
};

// slug → Simple Icons export key (`si<Brand>`). Unknown/removed keys resolve to
// undefined and fall through to the initial-tile fallback, so an optimistic key is
// always safe. phpbb + grav have no Simple Icons brand mark → intentionally absent.
const SI_KEY: Record<string, string> = {
  wordpress: "siWordpress",
  joomla: "siJoomla",
  drupal: "siDrupal",
  matomo: "siMatomo",
  nextcloud: "siNextcloud",
  mediawiki: "siMediawiki",
  prestashop: "siPrestashop",
  moodle: "siMoodle",
  // No Simple Icons brand mark — these use the initial-tile fallback: phpbb, grav
};

// A short human blurb per app for the wizard card. A slug with no entry falls back
// to a generic database/no-database line (keeps a newly-added recipe from breaking).
const BLURBS: Record<string, string> = {
  wordpress: "The world’s most popular CMS — installed and configured for you.",
  joomla: "Flexible open-source CMS for portals and complex sites.",
  drupal: "Enterprise-grade CMS for structured, high-volume content.",
  phpbb: "The classic open-source community forum.",
  matomo: "Privacy-friendly, self-hosted web analytics.",
  grav: "Fast flat-file CMS — no database needed.",
  nextcloud: "Your own private cloud for files, calendars and contacts.",
  mediawiki: "The wiki engine that powers Wikipedia.",
  prestashop: "Full-featured open-source e-commerce platform.",
  moodle: "The open-source learning management system.",
};

type SimpleIcon = { path?: string; hex?: string };

/** Resolve a Simple Icons glyph for a slug, or {} when the brand isn't carried. */
function resolveLogo(slug: string): { logoPath?: string; logoHex?: string } {
  const key = SI_KEY[slug];
  if (!key) return {};
  const icon = (simpleIcons as Record<string, unknown>)[key] as SimpleIcon | undefined;
  if (icon && typeof icon.path === "string") {
    return { logoPath: icon.path, logoHex: typeof icon.hex === "string" ? icon.hex : undefined };
  }
  return {};
}

/** The ordered one-click install menu for the deploy wizard. WordPress first, then
 *  every recipe app the worker supports, each enriched with a blurb + logo. */
export function hostingAppMenu(): HostingAppMenuItem[] {
  const items: HostingAppMenuItem[] = [
    // WordPress FIRST — fully automated via its own WORDPRESS_INSTALL task, so it is
    // not part of hostingAppCatalog(); prepend it here.
    { slug: "wordpress", name: "WordPress", needsDb: true, blurb: BLURBS.wordpress, ...resolveLogo("wordpress") },
  ];
  for (const app of hostingAppCatalog()) {
    items.push({
      slug: app.slug,
      name: app.name,
      needsDb: app.needsDb,
      blurb: BLURBS[app.slug] ?? (app.needsDb ? "Includes a database, set up for you." : "Lightweight — no database needed."),
      ...resolveLogo(app.slug),
    });
  }
  return items;
}

