/** One database row with inline "Show password" + "Reset" controls. Mirrors the
 *  SFTP reveal UX (HostingTabs) — the password is shown inline in mono, and a reset
 *  shows the freshly-generated password once with a "queued" note. */
function DbRow({ db }: { db: HostingDbView }) {
  const [pw, setPw] = useState<string | null>(null);
  const [reset, setReset] = useState<string | null>(null);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState<"show" | "reset" | null>(null);

  async function show() {
    setBusy("show");
    setErr("");
    try {
      const res = await revealHostingDbPassword(db.id);
      if (res.error) setErr(res.error);
      else setPw(res.password ?? "");
    } finally {
      setBusy(null);
    }
  }

  async function doReset() {
    setBusy("reset");
    setErr("");
    try {
      const res = await resetHostingDbPassword(db.id);
      if (res.error) setErr(res.error);
      else {
        setReset(res.password ?? "");
        setPw(res.password ?? "");
      }
    } finally {
      setBusy(null);
    }
  }

  return (
    <li className="text-slate-400">
      <div className="flex flex-wrap items-center gap-2">
        <span className="font-mono text-slate-200">{db.name}</span>
        <span className="text-slate-500">user {db.dbUser}</span>
        <span className={db.status === "ACTIVE" ? "text-emerald-300" : "text-amber-300"}>{db.status.toLowerCase()}</span>
        {pw ? (
          <span className="font-mono text-brand-200">{pw}</span>
        ) : (
          <button type="button" className="text-brand-300 hover:underline disabled:opacity-50" disabled={busy !== null} onClick={show}>
            {busy === "show" ? "…" : "Show password"}
          </button>
        )}
        <button type="button" className="text-slate-400 hover:underline disabled:opacity-50" disabled={busy !== null} onClick={doReset}>
          {busy === "reset" ? "…" : "Reset"}
        </button>
      </div>
      {reset && (
        <p className="mt-0.5 text-[11px] text-emerald-300/90">
          New password (shown once): <span className="font-mono text-emerald-200">{reset}</span> — queued, active in a moment.
        </p>
      )}
      {err && <p className="mt-0.5 text-[11px] text-amber-300">{err}</p>}
    </li>
  );
}

