/** Change a scoped MySQL user's password on the node (customer-initiated reset).
 *  Both identifiers are validated to safe charsets so the ALTER USER can't break
 *  out of its quotes — same escaping discipline as the scoped-grant tasks. */
async function taskResetDbPassword(conn: Client, a: { id: string }, payload: string | null): Promise<void> {
  void a;
  const p = JSON.parse(payload || "{}") as { dbUser?: string; passEnc?: string };
  const dbUser = String(p.dbUser ?? "");
  const pass = (p.passEnc ? decryptSecret(p.passEnc) : "") ?? "";
  if (!/^[a-z0-9_]{1,32}$/.test(dbUser) || !/^[A-Za-z0-9]{1,64}$/.test(pass)) throw new Error("invalid db credentials");
  const sql = sqlForMysqlExec(`ALTER USER '${dbUser}'@'localhost' IDENTIFIED BY '${pass}'; FLUSH PRIVILEGES;`);
  await run(conn, "reset db password", `mysql -e "${sql}"`);
}

